customScripts.auto_carousel_slider:
function __initAutoCarousel(root, ctx){
  if (!root) return;
  var initKey = 'mfAutoCarouselInit';
  if (root.dataset && root.dataset[initKey] === '1') return;
  if (root.dataset) root.dataset[initKey] = '1';

  var track = root.querySelector('.auto-carousel-track');
  var slides = Array.prototype.slice.call(root.querySelectorAll('.auto-slide'));
  var prevBtn = root.querySelector('.auto-carousel-prev');
  var nextBtn = root.querySelector('.auto-carousel-next');
  var dotsWrap = root.querySelector('.auto-carousel-dots');

  if (!track || !slides.length) return;

  var index = 0;
  var timer = null;
  var touchStartX = null;

  function getStepWidth(){
    if (!slides.length) return 0;
    var rect = slides[0].getBoundingClientRect();
    var styles = window.getComputedStyle(track);
    var gap = parseFloat(styles.gap || '0');
    return rect.width + (isNaN(gap) ? 0 : gap);
  }

  function getPerView(){
    var rect = root && root.getBoundingClientRect ? root.getBoundingClientRect() : null;
    var width = rect && rect.width ? rect.width : (window.innerWidth || 1200);
    if (width <= 500) return 1;
    if (width <= 800) return 2;
    if (width <= 1200) return 3;
    return 4;
  }

  function getMaxIndex(){
    return Math.max(0, slides.length - getPerView());
  }

  function clamp(value){
    var max = getMaxIndex();
    if (value < 0) return 0;
    if (value > max) return max;
    return value;
  }

  function updateButtons(){
    var max = getMaxIndex();
    if (prevBtn) prevBtn.disabled = index <= 0;
    if (nextBtn) nextBtn.disabled = index >= max;
  }

  function updateDots(){
    if (!dotsWrap) return;
    var dots = dotsWrap.querySelectorAll('.auto-dot');
    for (var i = 0; i < dots.length; i++) {
      dots[i].classList.toggle('active', i === index);
    }
  }

  function render(){
    var step = getStepWidth();
    track.style.transform = 'translateX(-' + (index * step) + 'px)';
    updateButtons();
    updateDots();
  }

  function goTo(i){
    index = clamp(i);
    render();
    resetAutoplay();
  }

  function next(){ goTo(index + 1); }
  function prev(){ goTo(index - 1); }

  function resetAutoplay(){
    if (timer) clearInterval(timer);
    timer = setInterval(function(){
      var max = getMaxIndex();
      index = index >= max ? 0 : index + 1;
      render();
    }, 5000);
  }

  if (prevBtn) prevBtn.addEventListener('click', prev);
  if (nextBtn) nextBtn.addEventListener('click', next);

  if (dotsWrap){
    var dots = dotsWrap.querySelectorAll('.auto-dot');
    dots.forEach(function(dot, i){
      dot.addEventListener('click', function(){ goTo(i); });
    });
  }

  track.addEventListener('touchstart', function(e){
    touchStartX = e.touches[0].clientX;
  });
  track.addEventListener('touchend', function(e){
    if (touchStartX === null) return;
    var diff = touchStartX - e.changedTouches[0].clientX;
    if (Math.abs(diff) > 50){
      if (diff > 0) next(); else prev();
    }
    touchStartX = null;
  });

  window.addEventListener('resize', render);
  render();
  resetAutoplay();
}
(function kickoff(){
  if (window.__autoCarouselReady) return;
  function tryInit(attempts){
    var root = window.__mfCurrentScriptRoot
            || document.querySelector('.mfp.auto-dealership')
            || document.querySelector('.auto-dealership');
    if (root && root.querySelector && root.querySelector('.auto-carousel-track')
             && root.querySelectorAll('.auto-slide').length > 0){
      window.__autoCarouselReady = true;
      try { __initAutoCarousel(root, window.__mfScriptContext || {}); }
      catch(e){ console.error('auto carousel init failed:', e); }
      return;
    }
    if (attempts < 40){ setTimeout(function(){ tryInit(attempts + 1); }, 100); }
  }
  if (document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ tryInit(0); });
  } else {
    tryInit(0);
  }
})();

